3	import com.example.starter.race.service.RaceService;
4	import com.example.starter.race.service.ServiceResult;
5	import jakarta.validation.Valid;
6	import org.springframework.http.ResponseEntity;
7	import org.springframework.web.bind.annotation.GetMapping;
8	import org.springframework.web.bind.annotation.PathVariable;
9	import org.springframework.web.bind.annotation.PostMapping;
10	import org.springframework.web.bind.annotation.RequestBody;
11	import org.springframework.web.bind.annotation.RequestMapping;
12	import org.springframework.web.bind.annotation.RestController;
13	/**
14	 * 赛事计时处罚与成绩封榜 HTTP 接口。
15	 */
16	@RestController
17	@RequestMapping("/api/races")
18	public class RaceController {
19	
20	    private final RaceService raceService;
21	
22	    public RaceController(RaceService raceService) {
23	        this.raceService = raceService;
24	    }
25	
26	    /** 新建赛事。 */
27	    @PostMapping
28	    public ResponseEntity<Object> createRace(@Valid @RequestBody CreateRaceRequest request) {
29	        return toResponse(raceService.createRace(request));
30	    }
31	
32	    /** 登记选手。 */
33	    @PostMapping("/{raceId}/runners")
34	    public ResponseEntity<Object> registerRunner(
35	            @PathVariable String raceId,
36	            @Valid @RequestBody RegisterRunnerRequest request) {
37	        return toResponse(raceService.registerRunner(raceId, request));
38	    }
39	
40	    /** 计时修订。 */
41	    @PostMapping("/{raceId}/timing-revisions")
42	    public ResponseEntity<Object> reviseTime(
43	            @PathVariable String raceId,
44	            @Valid @RequestBody ReviseTimeRequest request) {
45	        return toResponse(raceService.reviseTime(raceId, request));
46	    }
47	
48	    /** 新增处罚。 */
49	    @PostMapping("/{raceId}/penalties")
50	    public ResponseEntity<Object> addPenalty(
51	            @PathVariable String raceId,
52	            @Valid @RequestBody AddPenaltyRequest request) {
53	        return toResponse(raceService.addPenalty(raceId, request));
54	    }
55	
56	    /** 撤销处罚。 */
57	    @PostMapping("/{raceId}/penalties/{penaltyId}/revocation")
58	    public ResponseEntity<Object> revokePenalty(
59	            @PathVariable String raceId,
