19	import com.example.starter.race.persistence.SnapshotEntryRow;
20	import com.example.starter.race.persistence.SnapshotRow;
21	
22	import java.util.LinkedHashMap;
23	import java.util.List;
24	import java.util.Map;
25	
26	/**
27	 * 持久化行记录与 API 响应之间的转换。
28	 */
29	final class ResponseMapper {
30	
31	    private ResponseMapper() {
32	    }
33	
34	    static RunnerResponse toRunnerResponse(RunnerRow row) {
35	        return new RunnerResponse(row.bib(), row.finishTimeMs(), row.createdAt(), row.updatedAt());
36	    }
37	
38	    static PenaltyResponse toPenaltyResponse(PenaltyRow row) {
39	        return new PenaltyResponse(row.penaltyId(), row.bib(), row.type(), row.amountMs(),
40	                row.revoked(), row.createdAt(), row.revokedAt());
41	    }
42	
43	    static CheckpointTimingResponse toTimingResponse(CheckpointTimingRow row) {
44	        return new CheckpointTimingResponse(
45	                row.timingId(), row.bib(), row.checkpointCode(), row.position(),
46	                row.elapsedMillis(), row.createdAt());
47	    }
48	
49	    static StandingResponse liveStanding(
50	            RaceRow race,
51	            List<RunnerRow> runners,
52	            List<PenaltyRow> penalties,
53	            List<CheckpointRow> checkpoints,
54	            List<CheckpointTimingRow> timings) {
55	        List<ResultEntry> entries = ResultCalculator.compute(
56	                runners, penalties, checkpoints, timings);
57	        return new StandingResponse(
58	                race.raceId(),
59	                race.version(),
60	                race.status(),
61	                null,
62	                entries.stream().map(ResponseMapper::toEntryResponse).toList());
63	    }
64	
65	    static StandingResponse snapshotStanding(SnapshotRow snapshot) {
66	        return new StandingResponse(
67	                snapshot.raceId(),
68	                snapshot.version(),
69	                RaceStatus.SEALED,
70	                snapshot.sealedAt(),
71	                snapshot.entries().stream().map(ResponseMapper::toEntryResponse).toList());
72	    }
73	
74	    static ResultEntryResponse toEntryResponse(ResultEntry entry) {
75	        return new ResultEntryResponse(
76	                entry.bib(),
77	                entry.rank(),
78	                entry.status(),
79	                entry.finishTimeMs(),
80	                entry.penaltyMs(),
81	                entry.totalTimeMs(),
82	                entry.checkpointCount(),
83	                entry.coveredCheckpointCount(),
84	                entry.missingCheckpoints());
85	    }
86	
87	    static ResultEntryResponse toEntryResponse(SnapshotEntryRow entry) {
88	        return new ResultEntryResponse(
89	                entry.bib(),
90	                entry.rank(),
91	                entry.status(),
92	                entry.finishTimeMs(),
93	                entry.penaltyMs(),
94	                entry.totalTimeMs(),
95	                entry.checkpointCount(),
96	                entry.coveredCheckpointCount(),
97	                entry.missingCheckpoints());
98	    }
99	
100	    /**
101	     * 组装单个选手的分段明细：按检查点顺序，把已有通过记录映射到对应检查点，
102	     * 未通过的检查点 elapsedMillis/timingId 为 null。
103	     */
104	    static RunnerTimingResponse runnerTiming(
105	            RaceRow race,
106	            RunnerRow runner,
107	            List<CheckpointRow> checkpoints,
108	            List<CheckpointTimingRow> timings) {
109	        Map<String, CheckpointTimingRow> byCode = new LinkedHashMap<>();
110	        for (CheckpointTimingRow timing : timings) {
111	            byCode.put(timing.checkpointCode(), timing);
112	        }
113	        List<CheckpointPassResponse> passes = checkpoints.stream()
114	                .map(checkpoint -> {
115	                    CheckpointTimingRow timing = byCode.get(checkpoint.checkpointCode());
116	                    return new CheckpointPassResponse(
